INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Хурмоз яке аз бутӣҳои боғбоноии арзишманд ва талаботнокист, ки барои расидан ба қуллаи афзоиш ва мевадиҳии хос, ниёзманди парвариш ва назорати дақиқ ва ихтисосӣ мебошад. яке аз мушкилоти асосӣ ва доимӣ дар кишти хурмоз паҳн шудани вазъ ба ҳашарот ва бемориҳои кишоварӣ мебошад, ки метавонад боиси камшавии назаррас дар ҳаҷми ҳосил, паст шудани сифати меваҳо ва дар натиҷа, озимотҳои иқтисодии вазнин барои деҳқон гардад. Дар ин миён, истифодаи системаҳои муосири обёрӣи қатрагӣ ва тасмавӣ ҳалли ҷонгӣ ҳисоб карда мешавад, на танҳо дар идоракунӣ ва пешгирии ин мушкилот нақши босазз дорад, балки меъёрҳои кишти устуворро низ риоя менамояд. Ин системаҳои пешрафта бо расонидани мустақими об ба решаҳои бутӣ ва назорати дақиқи намнокорӣ шароити муҳитро аз афзоиш ва такрори заҳмвории занбӯрҳо ва ҳашарот берун мебарорад. Ҳамчунин, теъминоти назаррас дар истифодаи об ва кам шудани бисёри сатҳӣ, яке аз бенафъҳои барҷояи ин усул ҳисоб карда мешавад, ки бевосита ба кам шудани фишори физиологиии бутӣ ва мустаҳкам кардани системаи иммунии дар баробери омилҳои беморивазан таъсир мерасонад.</p>\n<h2>Муҳимтарин ҳашароти хурмоз ва нақши обёрӣи қатрагӣ дар назорати онҳо</h2>\n<p>Дар боғҳои парвариши ғилабида шуми ҳашароти мубтарӣ зиёданд, ки ба саломатии баргзор метавонанд зарари ҷиддӣ расонанд. Ба ҳашароти мубтар, ки баъзан ба ҳашароти зараровар низ ном доранд, метавон ҳашароти сурх, маҳси сиёҳи рудав, ғилабидаи сафед ва зард, инчунин ҳашароти қурбонаравро номбар кард, ки ҳар яке дарояди зарари худро дорад. Ҳашароти сурх махсусан дар шартҳои хушкории қавӣ ва камии рутубати назарӣ фаъол шуда, бо меҳкашкании хлорофилли баргзорҳо, сабабкунандаи зардикунии баргзорҳо ва кам шудани саросарии баргзорҳо мешаванд. Аз тарафи дигар, маҳси сиёҳи рудав дар шартҳои обшавӣ ва рутубати баланди хок фаъолият мекунад ва бо вайрон кардани рудавҳо ҷабби об ва моддаҳои ғизоиро мутаъташи кунад. Системи обёрӣ-нивагӣ, бо эҷоди мувозинати рутубат ва пешгирии нусҳои шиддати хушкӣ ё ғилолии хок, бевосита дар зидкунӣ ба шуми ин ҳашарот нақш мебозад. Бо кам шудани тамоси бевоситаи об бо сатҳи баргзорҳо, муҳит барои часпидагии хашароти қашоқӣ ва ҷабби баъзе ҳашароти парвозкунанда кам шуда, даври ҳаёти онҳо мутаъташ мешавад.</p>\n<h3>Нақши обёрӣ-нивагӣ дар кам кардани буғдорӣ ва пешгирии он</h3>\n<ul>\n<li>Кам шудани рутубати сатҳии хок ва пешгирии ҳосилшавии бастаки мувофиқ барои рушди спораҳои қашоқҳои хукишави хокӣ ва моҳигон</li>\n<li>Санҷиши дақиқтари ниёзи об вобаста ба синни баргзор ва пешгирии обшавии рудавҳо, ки сабаби асосии чобидшавӣ мебошад</li>\n<li>Истифодаи маҳлулҳои ғизоӣ ва баъзе моддаҳои зараровар бевосита ба рудавҳо (фертирӣ) ва кам шудани ниёз ба зарбзанандагони қиматии сатҳӣ</li>\n<li>Кам шудани тамоси бевоситаи об бо баргзорҳо ва пешгирии гузариши бемориҳои қашоқӣ тавассути зарба ва паршавии об</li>\n</ul>\n<p>Барои беҳтар кардани фаъолнокии системаи обикорӣ қатрӣ ва тақсимоти баробари об ба решагирӣ, шумо метавонед аз нӯрҳои (тасс) бешакҳои гуногун бо диаметри гуногун истифода баред. Интихоби намуди дурусти нӯр ба фосилаи ниҳодани хушмев ва чуқурии решагирии он вобаста аст ва обро бо тартиб ва баробарӣ ба решаҳои растани мерасонад ва аз ҷамъшавии об дар як нуқтаи муайян, ки метавонад боиси оборшавӣ ва беморӣ шавад, пешгирӣ мекунад.</p>\n\n<h2>Бемориҳои хушмев ва идоракунии онҳо дар шароити обикорӣ қатрӣ</h2>\n<p>Бемориҳои хушмев шомил дарайи бемориҳои кӯфакӣ, вирусӣ ва бактериявӣ аст, ки баъзеи онҳо тавассути хурак интиқол меёбанд ва дигарон бо воситаи ҳашарот ё ҳаво паҳн мешаванд. яке аз мӯррор ва ҳаромкортарин бемориҳо, гурбатшавии реша ва дарахтуру (тоҷ-гурбатшавӣ) аст, ки боиси ҷамъшавии зиёди об, кам будани ҳаво ба решаҳо ва фаъолияти кӯфакҳои фитопазоген мешавад. Дар системаи обикорӣ қатрӣ, ин хатар ба таври кониӣ ва ҷоҳам дидани кӯҳта мешавад, зеро об тавре баробар, идораишаванда ва бе ҷамъшавӣ дар қабатҳои чуқур ба решаҳо мерасад ва таъмини оксиген ба реша нигоҳ дошта мешавад. Инчунин, бемориҳои лангшавии баргҳо, ки аз кӯфакҳо ба миён омадааст ва дар ҳавои намнок ва тобиши бевасила ё обпашии сатҳӣ мулҳим аст, бо истифода аз обикорӣ қатрӣ тахти назорат меояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خربزه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های خربزه با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation хушмев</figcaption></figure>\n\n<h3>Пешгирии бемориҳои кӯфакӣ ва бактериявӣ</h3>\n<ol>\n<li>Истифодаи системаи обикорӣ қатрӣ ва пешгирии пашшакунии бевасилаи об ба баргҳо ва мевоеҳо, ки муҳити офтобидани кӯфак мебошад</li>\n<li>Санҷиши мунтазами системаҳои обикорӣ ва тозакунии филтрҳо барои пешгирии ҷамъшавии чанок (deposit) ва хоришшавии нӯрҳо, ки боиси симоҳои хушкшавӣ мешавад</li>\n<li>Ниҳодан дар шароити иқлимии мувофиқ ва санҷиши чуқурии ниҳодан, равонии хурак ва фосилаи кофӣ байни нохудаҳо барои ҳавогирии мувофиқ</li>\n<li>Оҳармонии дурусти истифодаи ғизо ва моавири муқобил ба занбӯрун, ки мувофиқанд, дар системаи обёрӣ ва шустушӯи мунтазами хатҳои бонти лубишӣ</li>\n</ol>\n<p>Бемориҳои бактериявӣ дар тарбузи хурда низ дар шароити бештар намнок ва оббозӣ паҳн мешаванд. Обёрӣ бо чархбандӣ тавассути муқаррар кардани мувозинати равои намнок ва боздошт аз пур шудани хӯрокҳои замин, ба зиёд шудани ин бактерияҳои зараровар мондагӣ мекунад. Инчунин метавон... <a href="https://navar-abyari.ir/foidai-norabiyari-tip/">Афзалиятҳои бонти обёрӣ лубишӣ</a> Барои баҳра бурдан аз афзалиятҳои усулҳои мазкур дар соҳаи тибби растанӣ, зеро ягонагии об ва ғизо стресси физиологии растаниро кам карда, муқовимати аслӣ-и онро дар назди таҳдидгарони берӯн баланд мебардорад.</p>\n\n<h2>Нуктаҳои амалӣ барои беҳтар кардани обёрӣ бо чархбандӣ барои тарбузи хурда</h2>\n<p>Барои бештар идоракунии зараргорон ва бемориҳои тарбузи хурда ва ба даст овардани маҳсулоти солим ва сифатнок, риъояи ягон нуктаҳои амалӣ дар тарҳрезӣ ва иҷрои системаи обёрӣ аз аҳамияти муҳим дорад. Аввалан, танзими дурусти ҷараёни об ва давраи обёрӣ дар системаи бонти лубишӣ аҳамияти калон дорад. Агар ҷараёни об ва вақти обёрӣ беш аз ҳад бошад, намноки иловагӣ дар замин ҷамъ мешавад ва заминаро барои роҳ ёфтани занбӯрунҳо ва бемориҳои занбӯрунамонии заминӣ месозад. Дар баробари ин, агар ҷараёни об ва шумораи даврҳои обёрӣ кам бошад, растанӣ ба дурдагӣ ва хушкӣ мерасад, ки муқовимати онро дар назди зараргорон монанди чархобҳо ва хушкадонҳо хеле кам мекунад ва меваҳоро дар назди таъом ва борабӣ зарарпазир месозад. Бинобар ин, муайян кардани дақиқи ниёзи ба об тарбузи хурда дар ҳама марҳилаҳои афзоиш (рӯшди хушкак, гургиди, мевадиҳӣ) зарур аст.</p>\n<h3>Санҷиши мунтазам ва нигоҳдории дурусти системаи обёрӣ</h3>\n<ul>\n<li>Санҷиши ҳафтонаки системаҳои обёрӣ ва тоза кардани филтрҳо ва сангчагириҳо барои боздоштан аз ибор шудани сӯроҳҳои бонт</li>\n<li>Дидангирӣ бар омадани фишори муносиби лӯлаҳо ва пайвастҳо барои пешгирии нӯкиши об ва кам шудани фишор дар охирин қисмҳои хатҳо</li>\n<li>Муайян кардани беҳтарин вақтҳои обёрӣ (афзал субҳи зодан ё шаб) бар асаси ниёзи рӯзонаи гиёҳ ва шароити ҳаво</li>\n<li>Истифодаи технологияҳои ҳақиқии ҳашарот ва сенсорҳои намдорӣ барои идоракунии худкори системаҳои обёрӣ ва пешгирии ҷамъ шудани намӣ</li>\n</ul>\n<p>Як дигар аз ҷанбаҳои муҳим, санҷиши чуқурӣи решаҳо ва масофаи муносиб байни занҷирагон аст. Хурмо-об (арбуз) одатан решаҳои нисбатан чуқур доранд ва дар шароити хушкӣ ё шӯрӣ хеле осебпазир мебошанд. Бо танзими дурусти системаи обёрии қатрагӣ метавон аз ин таҳдидуҳо пешгирӣ кард ва тақсимоти якхелаи моддаҳои ғизоӣ-ро таъмин намуд. Дар ин самт, шиносоии дақиқ бо <a href="https://navar-abyari.ir/qadamhoi-nasbi-navori-tip/">Қадамҳои насби навори дриллӣ</a> ба шумо кӯмак мекунад, ки системаро ба таври дуруст, бехатар ва бо камтарин нуқсолҳои техникиӣ насб кунед ва аз хазм шудани манбаъҳо пешгирӣ навмояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خربزه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های خربزه با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation хурмо-об</figcaption></figure>\n\n\n<h2>Саволҳои оддӣ дар бораи зарардиҳандагон ва бемориҳои хурмо-об дар обёрии қатрагӣ</h2>\n<h3>Оё оғозкунии қатрагӣ тамомен ивазкардани маҳсулоти химиявӣ мумкин аст?</h3>\n<p>Не, он тамомен иваз карда намешавад. Оғозкунии қатрагӣ усули иловагӣ ва пешгирикунанда аст, ки тавассути кам шудани намии иловагӣ, беҳтар шудани вазъияти хок ва эҷоди шароити муносиб барои рушди саломат, ҳадди зарурати маҳсулоти химиявиро ба таври дидашавандарӣ паст меорад. Аммо дар ҳолатҳои шадид ва паҳн шудани васеи баъзе зарароварони муайян ё бемориҳои системӣ, боз ҳам эҳтимоли зарурати истифодаи мақсаднок аз маҳсулоти химиявӣ ва муқаррикашҳои таъйиншуда вуҷуд дорад, то осеби бештар бароед.</p>\n<h3>Барои як гектар хурме чанд лӯлаи навақии тиубӣ лозим аст?</h3>\n<p>Миқдори лӯлаи навақии тиубӣ вобаста ба тартиби кишти, фосилаи байни сатҳҳо ва нармҳо ва чуқурӣи решагузишӣ мебошад. Одатан, барои ҳар як нарми хурме аз як ё ду навақии тиубӣ (дар ду тарафи нарм) истифода мешавад. Беҳтар аст, ки тавассути таҳқиқи дақиқи шароити мушаххаси дашт, намуди хок ва иқлими минтақа, шумора ва қобилияти навақияро ҳисоб кунед ва муайян намоед. Инчунин тавассути омӯзиши дастураи пурра дар бораи <a href="https://navar-abyari.ir/tips-before-buying-drip-tape-irrigation-iq/">нуктаҳои пеш аз харидани навақии оғозкунии тиубӣ</a> шумо метавонед беҳтарин интиҳоро дошта бошед ва аз харидани молу моллоти сифаташон паст ё бемувосифа худдорӣ кунед.</p>\n<h3>Оё истифодаи системаи оғозкунии қатрагӣ ба аҳват ва лаъзи хурме таъсир мерасонад?</h3>\n<p>Бале, ба таври мусбат ва дидашавандарӣ. Бо назорати дақиқи нам ва ғизои муносиб ва мӯҳим, гиёҳ қобилияти беҳтареро барои сохтани ва ҷамъ овардани моддаҳои аромикунона ва аҳват дар мева дорад. Инчунин кам шудани стрессҳои муҳитӣ ва пешгирӣ аз бемориҳо боиси истеҳсоли беҳтар аз аҳват ва лаъз дар меваи хурме мегардад ва сифати ниҳоии маҳсул аз ҷиҳати бозоришудӣ баланд мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خربزه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های خربزه با آبیاری قطره‌ای - تصویر 3"/><figcaption>zararoori va bemoriyhoi ziraat, oboriyi qatqat, tarvuz</figcaption></figure>\n\n<h2>Hulosah va taklifoti nihoi barои koradoron</h2>\n<p>Istifoda az sistemai oboriyi qatqati va noqib-tipe, яке аз стратегияҳои муъмар, иқтисодӣ ва устувор дар идоракунии зарароварон ва бемориҳои тарвuz ҳисоб карда мешавад. Бо кам кардани намдории иловагӣ ва эҷоди шартҳои мувофиқи хок ва реша, метавон ба таври назаррас аз паҳши зарароварон ва бемориҳои сафотӣ ва бактериявӣ пешгирӣ кард. Ин усул на танҳо ба таъсири калон дар сарфаи оби об ва энергия оварда мерасонад, балки бо баланд бардоштани сифати маҳсулот ва кам кардани талафот, фоиёти иқтисодии баландтарро низ таъмин мекунад ва ҳиссаи корандоро аз маҳсулоти саломаттар зиёд мекунад.</p>\n<p>Тавсияи ниҳоӣ ин аст, ки бо баррасии дақиқи шароити иқлим ва хокҳои моллаи худ, беҳтарин системаи обориро интихоб ва танзим намоед ва аз тавсияҳои мутахассисон истифода баред. Ҳамчунин истифода аз технологияҳои нав, ба монанди системаҳои идоракунии ҳашаманд, сенсорҳои намдор ва нармафзорҳои идоракунии молла, метавонад дақиқӣ ва самаранокии системаро ба таври ду баробар зиёд кунад. Дар натиҷа, бо риояи принсипҳои дурусти ғаллоқ, коҳиши растаниҳо ва обори стандартии, метавонед аз тарвuzҳои сифати баланд баҳраманд шавед, ки дар муқовимат ба зарароварон ва беморӣ мустаҳкамтар ва бехатартаранд ва фурӯши онҳо кафолатӣ мебошад.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/lettuce-yield-per-hectare-factors-increase/">lettuce yield per hectare factors increase</a></p>','Хашоротҳо ва бемориҳои хурбо дар системаи овардани об ба қуллаҳо: Раҳнамои куллӣ ва амалӣ','Дар ин мақолаи муфассал, усулҳои идоракунии зангорҳо ва бемориҳои хурмушакро дар системаи обкорӣ бо қутрашиносӣ кунед. Аз пешгирӣ то ҳалли мушкилоти маъмулӣ, ҳамаи чизҳое, ки бояд медонед.','publish','closed','closed','hazorot-ha-va-bemorihoi-khurbo-dar-sistemi-obari-qi-qaraboi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
