INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف حلول الإدارة المتكاملة للأمراض والآفات في حبوب العبادات (الريبي) المعتمدة على أنظمة الري بالتنقيط، مع تركيز على تقنيات الوقاية والعلاج الحديثة للمزارعين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
