INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарӣ: Аҳамияти таъсири ороғунибандӣ ва соҳтмонии ғаланбаи чинав ба чова</h2><p>Чова (<em>Secale cereale</em>) яке аз муҳимтарин шаклҳои гулестонаи соҳибии қатъӣ ба ҳамоҷоӣ, ки дар минтақаҳои сард ва нимсариш кунҷаккуниш шудааст. Бо тавассути технологияҳои навбунёди ороғунибандӣ, хусусан гуногуниҳои системаҳои ороғунибандӣ, кунҷаккунандагони минтақаҳои хушк дар ҳақиқат ба усулҳои камкунӣ истеъмоли об ва мусоидат ба соҳтмонии гулестон мекуҷанд. Ороғунибандии бӯсиданӣ ва бӯсиданӣ бо наварҳои нӯқс, бо марказ дар минтақаи реша, метавонад шароитҳои макро ва микро муҳитро тағйир диҳад. Ин тағйирот одатан замина барои ба вуҷуд овардани зараррасонҳои мушаххас ё тағйирот дар нақшаи пайдоиши беморҳои қаришавӣ ва бактериявиро мекунанд. Фаҳмиши дақиқи ин таъсирот калиди муваффақият дар идоракунии кунҷаккунии чова аст.</p><h2>Таъсири ороғунибандии бӯсиданӣ ба физикашумии хок ва решаи чова</h2><p>Дар системаи ороғунибандии бӯсиданӣ, намнокӣ зиёда дар байни фосилаҳо байни кӯппиҳо ба вуҷуд намеояд ва минтақаи хоки вобаста ба реша тобнок мемонад. Гарчанде ки ин аз зери таҳаммули хушкӣ нишонӣ медиҳад, вале метавонад муҳити гармтар ва намноктарро дар сатҳи хок дар атрофи реша ба вуҷуд орад. Чова, бо сабаби решаҳои чуқур ва стилиарӣ, аз ин шароитҳои хос истифода мебарад, вале агар идоракунии намнокӣ номувофиқ бошад, хатари беморҳои реша бартар мегирад. [[IMAGE_1]] Дар бӯсиданӣ бо навар низ, парокандагии якхелаи об дар наварҳои торики метавонад сабабшавии зичкунӣ зиёда намнокӣ дар сатҳ бошад, ки барои зараррасонҳои хокзиста ҷалбкунанда аст.</p><h3>Тағйирот дар нақшаи намнокӣ ва робита бо қаришавиҳо</h3><p>Намнокии давомнок сатҳи хок яке аз омили асосӣ дар фаъолкунии хакаҳои қаришавиҳои патогенӣ ба монанди <em>Pyrenophora</em> ва <em>Septoria</em> ҳо. Ин занбӯруҳо одомиро дар шароити намнок ба баргҳо ҳуҷум мекунанд. Агар обдорӣ бо тарозҳо боиси паршуни об ба баргҳо шавад, хавфи сироятшавии дараҷаи дуюм зиёд мешавад. Бинобар ин, тарҳрезии система тавре, ки об танҳо ба хок мерасад, яке аз принсипҳои асосии пешгирии сироятшавии занбӯругӣ мебошад.</p><h2>Афати маъмултарини ҷав дар шароити обдории маҳаллӣ</h2><p>Афати доираи хок ва муҳити намноктар дар системаҳои обдории маҳаллӣ аҳамияти махсусӣ мегиранд. Дар поён ба муҳимтарин афатҳо мерасем:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-چاودار-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های چاودار با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation чaодар</figcaption></figure><ol><li><strong>Ширешакҳои решагӣ ва хокзистӣ:</strong> Зиёдшавии намнокӣи нисбии ҳамои равиш метавонад шомилоти афати хокзистиро ба таври нисбӣ зиёд кунад. Ин афатҳо бо чашонидан ба реша, ҷузъи об ва моддаҳои ғизоииро камтар мекунанд ва заифии умумии баҳоро ба вуҷуд меоранд.</li><li><strong>Аракиҳо ва дурҳаҳмонҳо:</strong> Ҳоло, ки обдории тарозҳо одомиро нисбат ба обдории боронӣ хушкитар нигоҳ медорад, вале минтақаҳои намноки банди дилгаштӣ метавонад паноҳгоҳи муносиб барои бачаҳои аракиҳо бошад. Тозии минтақаҳои ҳошияи боғ хеле зарур аст.</li><li><strong>Парҳаҳои деҳқорӣ ва паррандагӣ:</strong> Ин масъала бештар ба марҳилаи гулбарорӣ рабт дорад, аммо саломатии кӯдакони растаниҳо, ки бо сабаби камшавии об ё фишори зангингӣ суст шудаанд, парҳаҳоро ба самони дӯдакҳо ҷалб мекунад.</li></ol><h2>Бемориҳои зангингӣ ва бактериалӣ: мушкилоти асосӣ</h2><p>Бемориҳо дар рож, ки бо обӣ кардан бо усули қатраӣ сиробӣ мешаванд, намунаи гунаро ба муқоиса бо борон нишон медиҳанд. Бемориҳои муҳимтарин чунинҳо мебошанд:</p><ul><li><strong>Зангҳои рож (Rusts):</strong> Занги сафед ва занги қафӣ дар шароити рағубат ва сард фаъол мешаванд. Дар ҳолати обӣ кардан бо усули қатраӣ, агар ҳудуди нисбии ҳавои атрофи гулҳо баланд шавад, паҳншавии зангҳо бартарӣ мегирад.</li><li><strong>Фузариозии реша ва сабук:</strong> Занг <em>Fusarium</em> Он ба ҳарорати баланд дар замина бо таррагии баланд шод аст. Ин қаламфури боиси шӯстани реша ва дарахт мешавад, ки ба зардонӣ ва хушкшавии ҷиҳат оварда мерасонад.</li><li><strong>Гӯштшавии бирёкаи қаймоқӣ:</strong> Ин беморӣ ҳам бактериявӣ ва ҳам қаламфурии аст ва тавассути захамоти реша дар минтақаҳои тарраки рӯйаи тӯб тарқ мекунад.</li></ul><h2>Роҳҳои амалии идоракунии зараррасонҳо ва бемориҳо дар системаи қатқатонакӣ</h2><p>Барои идоракунии муассир, омехтаи чораҳои пешгиракӣ ва табибӣ лозим аст:</p><h3>Идоракунии минтақаҳои таррак ва хушки рӯйаи тӯб</h3><p>Аҳамияти намунагирии мунтазами замина барои муайян кардани нақари тарракӣ доранд. Тавсия мешавад, ки аз истифодаи оби зарари заминаи ифторнок дар системаи қатқатонакӣ худдорӣ карда шавад, зеро он метавонад мавзӯи патогенҳои зарари замина бошад. Шустани филтрҳои системаи обёрӣ барои пешгирӣ аз гиҷидан ва эҷоди муҳит барои рӯшани бактерияҳо дар дарунпӯшҳо зарур аст.</p><h3>Муборизаи биологӣ ва назорати табиӣ</h3><p>Дар системаҳои қауқумавӣ об мустақиман ба баргҳо паршонида намешавад, бинобар ин аз ширбҳои занбӯриҳои фоиданок, чунин <em>Trichoderma harzianum</em> истифода бурдан мумкин аст, ки онҳо тавассути оби обироӣ ба решаҳо зарб дода мешаванд. Ин усул рақобатро бо патогенҳо дар минтақаи решаҳо афзун мекунад ва бе инкиҳои намии сатҳӣ, муҳитро тоза мекунад. [[IMAGE_2]] Ҳамагӣ, нигоҳдошти бисёр навъиятҳо бо сохтани сутунҳои баргҳои бумедӣ метавонад чароғҳоро ҷалб кунад ва ба назорати занҷир, чун хӯки, кӯмак расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-چاودار-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های چاودار با آبیاری قطره‌ای - تصویر 2"/><figcaption>зангиҳои фармонҳои ҳосилот, обии қауқумавӣ чӯғудор</figcaption></figure><h3>Барномаёнии дақиқи кимиёвӣ</h3><p>Агар зарурати кимиёвӣ вуҷуд дошта бошад, истифода аз шаклҳои системикӣ, ки тавассути решаҳо ҷаббида мешаванд (масалан, баъзе занбӯрконҳо аз гурӯҳи триазолҳо), ба паршониҳои маҳаллӣ сатҳӣ самараноктар аст. Дозаи истифода бояд асосан бо арзиши иқтисодӣ ва назорати дақиқ муайян шавад, то бактерия ва занбӯрҳои фоиданоки хок кушта нашаванд. Дар ин самт, омӯзиш <a href="https://navar-abyari.ir/mikdori-tuhmiy-javorimakshidon-hoti-gakhtar/" target="_blank">миқдори тасими пайдои инди ҳосилот</a> метавонад муҳандисии дозаи истифода дар дигар маҳсулотно и оптимизатсия кунад.</p><h2>Назорат ва муайянкунии баҳорӣ: Рӯшнонамои ҳошё</h2><p>Нигоҳубинии мунтазам дар системаҳои ободории маҳаллӣ ҳартиҷоҳӣ аст, зеро зарарнокӣ дар минтақаҳои намнок пинҳон мемонад.</p><ol><li><strong>Озmosи бёёрӣ аз реша ва шохмон:</strong> Пеш аз ҳар маротиба оборӣ, намунагирии реша дар фосилаи 50 сантиметрӣ аз қатравҳо иҷро карда шавад, то нисшҳои термориз (Thermocis) баррас карда шаванд.</li><li><strong>Нигоҳубини ҳашарот:</strong> Истифодаи туғҳои сархан (Yellow Traps) дар минтақаҳои намноки нӯри Тиб барои тавозини занозаҳои иттилоот (интиқолдиҳанда) ва дигар ҳашароти ҳасобноки (қисми ҳасобнок).</li><li><strong>Нигоҳубини филтрҳо:</strong> Санҷиши шусҳо (шифо)и обро аз филтрҳо барои муайян кардани афзоиши заргӣ ва бактерияҳо дар дохили система.</li></ol><h2>Фaq: Саволҳои маъмул дар бораи интиқолдиҳандагон ва бемориҳои чодар</h2><ul><li><strong>Оё ихтиёри оқимӣ (каплӣ) боиси зиёд шудани бемориҳои занбӯрунии човдар мешавад?</strong> Не, агар система дуруст идора шавад, кам шудани намӣ дар ҳаваи атрофи баргҳо аз бемориҳои сарбандӣ пешгирии мекунад. Аммо рехтани об ба реша метавонад бемориҳои решагӣро бадтар созад, ки бо истифода аз зарардиҳандаҳои биологӣ ҳал мешавад.</li><li><strong>Беҳтарин вақт барои муайян кардани зарардиҳандаҳои хокӣ дар човдар кадом аст?</strong> Марҳилаҳои аввали равояти (бардоштан) вақти мувофиқ аст. Дар ин вақт, беморӣ ҳисоби озодагӣ нисбат ба камшавии моддаҳои ғизоӣ баландтар аст ва зарари ба решаҳо ба таври тезтар нишон дода мешавад.</li><li><strong>Оё имкон дорад, ки дар системаи ихтиёрӣ (каплӣ) инсектицидҳои системӣ истифода шаванд?</strong> Бале, баъзе инсектицидҳо имконияти инъеқсӣ тавассути суғор (Soil Injection) доранд. Ин роҳ барои идоракунии мушакиҳои хокӣ хеле самаранок аст.</li></ul><h2>Хулоса ва тавсияҳои охирин</h2><p>Идоракунии зарардиҳандагон ва бемориҳо дар човдар дар системаи ихтиёрӣ (каплӣ) ба равиши ягона ва ҳушманд ниёз дорад. Тағйироти майлӣ дар намии хок метавонад мувозинати экологии майдонро вайрон ё нигоҳ дорад. Кишоварон бояд ба назорати решаҳо, истифодаи биологҳои системӣ ва нигоҳдории дурусти филтрҳо диққат диҳанд. Бо татбиқи принсипҳои ихтиёрии каплӣ метавон нафаскашии обро идора кард ва солимӣи бемориро нигоҳ дошт. Ояндаи кишоварии устувор ба фикри дақиқ дар муносибатҳои суғор ва беморшиносӣ вобаста аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-چاودار-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های چاودار با آبیاری قطره‌ای - تصویر 3"/><figcaption>зараргардон ва бемориҳои фармаси, обёркунии тамулӣ, чавдар</figcaption></figure><p>Барои таҳаввулоти дониш дар соҳаи маҳсулоти дигар, омӯзиш <a href="https://navar-abyari.ir/onion-yield-per-hectare-iraq/" target="_blank">Бемориҳои пиёз дар ҳектари Ироқ</a> метавонад дидгоҳи муқоисавии фоидамандро барои дарк кардани бемориҳои рӯякҳои гандумгӣ пешниҳод намояд.</p><p>[[IMAGE_3]]</p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/agricultural-collapsible-hose-guide/">agricultural collapsible hose guide</a>, <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D9%84%D9%88%D8%A8%DB%8C%D8%A7-%D8%B3%D8%A8%D8%B2-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D984D988D8A8DB8CD8A7 D8B3D8A8D8B2 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Нубуҳодику ва бемориҳои ржи дар системаи оварии буттавӣ: Роҳнамои умумии идоракунӣ','Осувӣ по-qатроӣ гарчанде коркарди обро беҳтар менамояд, вале нақши намии хокро тағйир дода метавонад экосистемеро ба вуҷуд орад, ки баъзе зараррасонҳои хокӣ ва бемориҳои занбоорӣро шиддат ё заиф мекунад. Дар ин мақола, роҳҳои идоракунии зараррасонҳо ва бемориҳои араваро дар фокус ба хусусиятҳои нақши qатроӣ ва қаторӣ баррасӣ мекунанд, то самаранокӣ ва солимнокии ғаладонҳои араваро бо нигоҳ доштани хоси хуб.','publish','closed','closed','nubuhodik-va-bemorihoyi-rji-dar-systema-obar-buttaviy',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
